// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        c.addReward(address(0x1));

        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == true || ok == false);

        if (ok) {
            assertTrue(c.owner() == address(0));
        } else {
            assertTrue(c.owner() == address(this));
        }

        assertTrue(!ok && c.owner() == address(this));
    }
}
